  "steps": [
    {
      "id": 1,
      "claim": "For a concave mirror the mirror equation is 1/f = 1/d_o + 1/d_i, with f > 0.",
      "evidence": "Standard thin‑mirror formula derived from geometry of spherical mirrors.",
      "weight": 0.2,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Linear magnification is m = -d_i / d_o.",
      "evidence": "Definition of magnification for mirrors (image height / object height).",
      "weight": 0.2,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "When the object is at infinity (d_o → ∞), the image distance d_i = f.",
      "evidence": "Set 1/d_o → 0 in the mirror equation: 1/d_i = 1/f ⇒ d_i = f.",
      "weight": 0.1,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "As the object distance d_o decreases from a large value toward f (but stays > f), the image distance d_i increases without bound (d_i → ∞).",
      "evidence": "From the mirror equation, 1/d_i = 1/f – 1/d_o. As d_o → f⁺, 1/d_o → 1/f⁻, so the right‑hand side → 0⁺, giving d_i → +∞.",
      "weight": 0.2,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "The magnitude of magnification |m| = d_i / d_o = f / (d_o – f) grows without bound as d_o → f⁺, so the image becomes taller.",
      "evidence": "Substitute d_i = f·d_o/(d_o – f) into m = -d_i/d_o; then |m| = f/(d_o – f). The denominator → 0⁺, so |m| → ∞.",
      "weight": 0.2,
      "depends_on": [2, 4]
    },
    {
      "id": 6,
      "claim": "Therefore, as the object moves from far away to near the focal point, the image moves away from the mirror and gets taller.",
      "evidence": "Step 4 shows the image distance increases (moves away); step 5 shows magnification magnitude increases (image height increases).",
      "weight": 0.1,
      "depends_on": [4, 5]
    }
  ],
  "answer": "B",
  "confidence": 0.98,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "The image moves away from the mirror, but it gets taller, not shorter."
    },
